<?php namespace App\Domains\Comercial\LiveSales\Actions; use App\Domains\Auditoria\DTOs\RegistrarAuditoriaData; use App\Domains\Auditoria\Services\RegistrarAuditoriaService; use App\Domains\Comercial\LiveSales\Services\LiveSalesService; use App\Models\InteraccionLive; use App\Models\SesionLive; class RegistrarInteraccionLiveAction{ public function __construct(private readonly LiveSalesService $service, private RegistrarAuditoriaService $auditoriaService){} public function execute(SesionLive $sesion,array $data):InteraccionLive{ $this->service->validarSesionParaInteraccion($sesion); $interaccion = InteraccionLive::create($data); $contexto = RegistrarAuditoriaData::fromRequest(request()); $this->auditoriaService->registrarInsercion($contexto, 'LiveSales', 'interacciones_live', (string) $interaccion->cod_interaccion_live); return $interaccion; } }
